arguments.file_text:
#:property AllowUnsafeBlocks=true

using System;
using System.Runtime.InteropServices;

Console.WriteLine($"nint size: {sizeof(nint)} bytes ({nint.Size * 8}-bit)");

// stackalloc nint into a Span
Span<nint> signedSpan = stackalloc nint[4];
for (int i = 0; i < signedSpan.Length; i++)
    signedSpan[i] = (nint)(i * 100);

Console.WriteLine("\nSpan<nint> via stackalloc:");
foreach (var v in signedSpan)
    Console.WriteLine($"  {v}");

// stackalloc nuint into a Span
Span<nuint> unsignedSpan = stackalloc nuint[4];
for (int i = 0; i < unsignedSpan.Length; i++)
    unsignedSpan[i] = (nuint)(i * 200);

Console.WriteLine("\nSpan<nuint> via stackalloc:");
foreach (var v in unsignedSpan)
    Console.WriteLine($"  {v}");

Console.WriteLine("\n✅ stackalloc with nint/nuint into Span works!");

